// Explicit recovery for a returning wallet. Discovery uses player-filtered
// events once, then cached tails; only unresolved records are read again.
import { eventFacts } from './facts.js';
import { readArtifact, writeArtifact } from './event-store.js';
import { checkAbort } from './client.js';

export async function pendingBets(s, player, signal) {
  const rows=await eventFacts(s,['DegeneretteBetPlaced','DegeneretteResolved'],{contract:'GAME',player,signal});
  const resolved=new Set(rows.filter(e=>e.name==='DegeneretteResolved').map(e=>e.args.betId));
  const candidates=rows.filter(e=>e.name==='DegeneretteBetPlaced'&&!resolved.has(e.args.betId));const result=[];
  for(let i=0;i<candidates.length;i+=25){
    checkAbort(signal);
    const found=await Promise.all(candidates.slice(i,i+25).map(async row=>{
      const packed=await s.field('GAME','degeneretteBets',player,row.args.betId);
      return packed ? {betId:row.args.betId,betIndex:Number(row.args.index),packedData:String(packed)} : null;
    }));result.push(...found.filter(Boolean));
  }
  return result;
}
export async function pendingBoxes(s, player, signal) {
  const key=`box-recovery:${s.client.chain.id}:${s.client.address('GAME')}:${player}`;
  let saved=await readArtifact(key);
  if(saved && (saved.block>s.block.number || (await s.client.header(saved.block,signal)).hash!==saved.hash))saved=null;
  const closed=new Set(saved?.closed??[]);
  const buys=await eventFacts(s,['LootBoxBuy','PresaleBoxBuy'],{contract:'GAME',player,signal});
  const byOrder=new Map(buys.map(e=>[`${e.name}:${e.args.index}`,e])); const result=[];
  const candidates=[...byOrder].filter(([key])=>!closed.has(key));
  for(let i=0;i<candidates.length;i+=25){
    checkAbort(signal);
    const wave=await Promise.all(candidates.slice(i,i+25).map(async([key,row])=>{
      const [pending,word]=await Promise.all([s.field('GAME',row.name==='PresaleBoxBuy'?'presaleBoxEth':'lootboxOrder',row.args.index,player),s.field('GAME','lootboxRngWordByIndex',row.args.index)]);
      if(!pending && word){closed.add(key);return null;}
      return pending?row:null;
    }));result.push(...wave.filter(Boolean));
  }
  await s.verify(signal);writeArtifact(key,{block:s.block.number,hash:s.block.hash,closed:[...closed]});
  return result;
}
